'use strict';

// MODULES //

var str2enum = require( '@stdlib/ndarray/base/dtype-str2enum' );


// MAIN //

/**
* Converts dtype strings to numeric enum values and returns them as a JSON array string.
*
* @private
* @param {Array} matches - array of match entries
* @returns {string} JSON stringified array of dtype enum values
*
* @example
* var matches = [
*     [ 'float32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_f_d_as_d_d' ],
*     [ 'float32', 'float32', '@stdlib/math/base/special/acosdf', false, null, null, 'stdlib_base_acosdf', 'stdlib_ndarray_f_f' ],
*     [ 'float64', 'float64', '@stdlib/math/base/special/acosd', false, null, null, 'stdlib_base_acosd', 'stdlib_ndarray_d_d' ],
*     [ 'float64', 'float32', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_d_f_as_d_d' ],
*     [ 'int32', 'float64', '@stdlib/math/base/special/acosd', true, 'float64', 'float64', 'stdlib_base_acosd', 'stdlib_ndarray_i_d_as_d_d' ]
* ];
* var result = extractTypesJsonArray( matches );
* // returns <string>
*
* // The returned string is a JSON array of dtype enum pairs:
* // '[11,12,11,11,12,12,12,11,7,12]'
*
* // Each pair represents (inputType, outputType) enum values
*/
function extractTypesJsonArray( matches ) {
	var typeEnums;
	var i;

	typeEnums = [];
	for ( i = 0; i < matches.length; i++ ) {
		typeEnums.push( str2enum( matches[ i ][ 0 ] ) );
		typeEnums.push( str2enum( matches[ i ][ 1 ] ) );
	}

	return JSON.stringify( typeEnums );
}


// EXPORTS //

module.exports = extractTypesJsonArray;
